export type ScenarioAnalysisRequest = {
    /**
     * Scenario analysis mode. 'filter' builds distribution by filter conditions (markets, products, supply_paths, gl_accounts, period). 'balance' builds distribution by calculating all nodes of a selected GL Balance tree.
     */
    mode?: 'filter' | 'balance';
    /**
     * Selected market values from the delivery_markets dictionary. OR within the list. (filter mode only)
     */
    markets?: Array<(string)> | null;
    /**
     * Selected GL account values. OR within the list. (filter mode only)
     */
    gl_accounts?: Array<(string)> | null;
    /**
     * Selected product values from the products dictionary. OR within the list. (filter mode only)
     */
    products?: Array<(string)> | null;
    /**
     * Scoped include/exclude rules. Values within a dimension are OR-ed; dimensions within a rule are AND-ed; rules of the same action are combined by OR.
     */
    filter_rules?: Array<{
    [key: string]: unknown;
}> | null;
    /**
     * Selected supply path values from the supply_paths dictionary. OR within the list. (filter mode only)
     */
    supply_paths?: Array<(string)> | null;
    /**
     * Period filter mode. 'valuations' applies month filtering using hive partitions valuation_year/valuation_month. 'payments' applies month filtering using payment_period. Balance mode is payments-based and uses the tree year as YEAR(payment_period).
     */
    period_mode?: 'valuations' | 'payments';
    /**
     * Reporting currency for scenario revenue aggregation. Supported values are defined by the scenario analysis service. (filter mode only)
     */
    currency?: string;
    /**
     * Inclusive lower bound for valuation_period. Interpreted at month granularity. (filter mode only)
     */
    period_from?: string | null;
    /**
     * Inclusive upper bound for valuation_period. Interpreted at month granularity. (filter mode only)
     */
    period_to?: string | null;
    /**
     * GL tree slug for balance mode. Required when mode='balance'.
     */
    balance_tree_slug?: string | null;
    /**
     * Optional scenario slug to filter simulation results to a specific scenario partition. When not provided, results are aggregated across all scenarios.
     */
    scenario?: string | null;
    /**
     * Observation date used to select the simulation observation_date partition.
     */
    observation_date: string;
    /**
     * Valuation type partition used by both filter mode and balance mode. When omitted, eod is used for backward compatibility.
     */
    valuation_type?: string | null;
    /**
     * Optional simulation source selector. UUID-like values resolve exact MCMF sources; slug-like values resolve to the latest matching observation_date partition; YYYY-MM-DD/slug pins the simulation source date explicitly.
     */
    operation_id?: string | null;
    /**
     * Date scope used to aggregate factor values for scenario weights. 'full_selected_period' uses the full selected period; 'forecast_period' uses only dates strictly after observation_date.
     */
    shock_scope?: 'full_selected_period' | 'forecast_period';
    /**
     * Interpretation for scenarios with two or more non-zero factor shocks. 'exact_targets' treats entered percentages as final target factor shifts; 'market_amplification' treats them as separate marginal impacts. For fewer than two non-zero shocks exact_targets is used.
     */
    joint_shock_mode?: 'exact_targets' | 'market_amplification';
    /**
     * Per-factor shocks for brent, ttf and usdrub
     */
    shocks: Array<ScenarioFactorShock>;
    /**
     * Bootstrap sample size for each generated scenario
     */
    n_bootstrap?: number;
    /**
     * Deterministic random seed used for scenario generation
     */
    random_seed?: number;
    /**
     * Include raw bootstrap sample values in the response. When false (default), only density and stats are returned — recommended for density chart mode. Set to true when box/violin chart is needed.
     */
    include_values?: boolean;
};

/**
 * Scenario analysis mode. 'filter' builds distribution by filter conditions (markets, products, supply_paths, gl_accounts, period). 'balance' builds distribution by calculating all nodes of a selected GL Balance tree.
 */
export type mode = 'filter' | 'balance';

/**
 * Period filter mode. 'valuations' applies month filtering using hive partitions valuation_year/valuation_month. 'payments' applies month filtering using payment_period. Balance mode is payments-based and uses the tree year as YEAR(payment_period).
 */
export type period_mode = 'valuations' | 'payments';

/**
 * Date scope used to aggregate factor values for scenario weights. 'full_selected_period' uses the full selected period; 'forecast_period' uses only dates strictly after observation_date.
 */
export type shock_scope = 'full_selected_period' | 'forecast_period';

/**
 * Interpretation for scenarios with two or more non-zero factor shocks. 'exact_targets' treats entered percentages as final target factor shifts; 'market_amplification' treats them as separate marginal impacts. For fewer than two non-zero shocks exact_targets is used.
 */
export type joint_shock_mode = 'exact_targets' | 'market_amplification';

